import { Component, OnInit } from '@angular/core';
import { FormGroup, FormBuilder, Validators } from "@angular/forms";
import { ActivatedRoute, Router }    from '@angular/router';

import { Observable } from 'rxjs/Observable';
import 'rxjs/add/observable/forkJoin';
import 'rxjs/add/operator/map';

import { CustomerService } from "../_shared/customer.service";
import { ProductsService } from "../../products/_shared/products.service";

@Component({
  selector: 'app-customer-products',
  templateUrl: './customer-products.component.html',
  styleUrls: ['./customer-products.component.scss']
})
export class CustomerProductsComponent implements OnInit {
  isLoading = false;
  customerId = '';
  customerProductForm: FormGroup;
  products = [];
  customerProductIds = [];
  productSelected = [];
  productUnselected = [];


  constructor(
    private fb: FormBuilder,
    private customerService: CustomerService,
    private productService: ProductsService,
    private route: ActivatedRoute,
    private router: Router
  ) { }

  ngOnInit() {
    this.customerId = this.route.snapshot.paramMap.get('id');

    if (this.customerId){

      this.isLoading = true;

      Observable.forkJoin([
        this.customerService.getCustomerProducts(this.customerId),
        this.productService.getProducts()
      ]).subscribe(
        results => {
          this.products = results[1];
          this.customerProductIds = results[0];
          this.generateLists();
          this.isLoading = false;
        }
      );

    } 

    this.createForm();

  }

  createForm(){
    this.customerProductForm = this.fb.group({
      productId: ['']
    });
  }

  generateLists(){
    this.productSelected = this.products.filter(product => this.customerProductIds.findIndex(id => id === product._id) >= 0);
    this.productUnselected = this.products.filter(product => this.customerProductIds.findIndex(id => id === product._id) < 0);
  }

  selectProduct(){
    const formModel = this.customerProductForm.value;

    this.customerProductIds.push(formModel.productId as string);
    this.generateLists();

    this.customerProductForm.reset({
      productId: ''
    });
  }

  unselectProduct(customerProductId){
    const customerProductIndex = this.customerProductIds.findIndex(id => id === customerProductId);

    if (customerProductIndex >= 0){
      this.customerProductIds.splice(customerProductIndex, 1);
    }

    this.generateLists();
  }

  save(){
    this.customerService.editCustomerProducts(this.customerId, this.customerProductIds).subscribe(
      res => {
        this.router.navigate(['/customers/' + this.customerId]);
      },
      error => console.log(error)
    );
  }
}
